<?php
declare(strict_types=1);require dirname(__DIR__,2).'/system/app/bootstrap.php';require dirname(__DIR__,2).'/system/ui/layout.php';$user=enterprise_require_auth('../../');try{$pdo=enterprise_pdo();enterprise_upgrade($pdo);$products=$pdo->query('SELECT * FROM installed_products ORDER BY id')->fetchAll();$error='';}catch(Throwable $e){$products=[];$error=$e->getMessage();}ob_start();?><?php render_breadcrumbs([['label'=>'Enterprise','href'=>'../dashboard.php'],['label'=>'Produkte','href'=>'']]); ?><section class="hero"><span class="badge">Produktregister</span><h1>Produkte</h1><p>Verfügbare und vorbereitete easyIT-Produkte.</p></section><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><div class="cards product-grid"><?php foreach($products as $p):?><article class="card"><span class="status-pill <?=e($p['status'])?>"><?=e($p['status'])?></span><h2><?=e($p['label'])?></h2><p>Version: <?=e($p['version']??'noch nicht verfügbar')?></p></article><?php endforeach;?></div><?php $content=ob_get_clean();render_page(['title'=>'Produkte','active'=>'products','base'=>'../../','content'=>$content,'app_nav'=>true,'user'=>$user,'help'=>['title'=>'Produktregister','location'=>'Enterprise → Produkte','short'=>'Übersicht über alle Enterprise-Produkte.','goal'=>'Verfügbare Produkte für Projekte erkennen.','tips'=>['RC1.1.1-dev aktiviert zunächst DataForm.']]]);